let premiumVerified = false;
async function verifyPremium(){
  premiumVerified = false;
  if (location.protocol === 'file:') return false;
  try {
    const response = await fetch('/api/subscription/status', {credentials:'include',cache:'no-store'});
    if(!response.ok) return false;
    const data = await response.json();
    premiumVerified = data && data.premium === true;
  } catch (_) { premiumVerified = false; }
  return premiumVerified;
}
function quizLocked(){return `<div class="eyebrow">Entraînement réservé aux abonnés</div><div class="lock premium-gate"><div class="gate-icon" aria-hidden="true">🔒</div><h1>Quiz réservé à Premium</h1><p>Les 72 questions, les indices et les corrections détaillées sont accessibles avec un abonnement Premium actif.</p><p class="muted">Aucun abonnement n'a été confirmé pour cette session. En mode fichier local, le quiz reste fermé car aucun serveur ne peut vérifier un paiement.</p><div class="actions"><button class="primary" onclick="go('offres')">Découvrir l’abonnement Premium →</button><button class="ghost" onclick="refreshSubscription()">Vérifier mon abonnement</button></div><p id="subscription-feedback" class="muted" aria-live="polite"></p></div>`}
async function refreshSubscription(){
  const label=$('subscription-feedback');if(label)label.textContent='Vérification en cours…';
  const active=await verifyPremium();
  if(location.hash==='#quiz'||/^#p-\d+$/.test(location.hash)){
    if(active){route();}else if($('subscription-feedback'))$('subscription-feedback').textContent='Aucun abonnement actif confirmé. Pour un accès réel, connecte le site à un serveur avec Stripe.';
  }
}
function quiz(){return `<div class="eyebrow">72 questions · 12 chapitres</div><h1>Quiz de cybersécurité</h1><p class="lead">Découvre une explication pour chaque réponse, utilise un indice et recommence les questions ratées.</p><div class="lock"><strong>Accès Premium vérifié</strong><p>Le quiz n’est transmis que lorsque le serveur confirme un abonnement Premium actif.</p></div><div class="card quiz-box"><div class="quiz-controls"><div><label for="topic">Chapitre à réviser</label><select id="topic" class="field"><option value="all">Tous les chapitres</option>${DATA.chap.map((x,i)=>`<option value="${i}">${i+1}. ${clean(x.title)}</option>`).join('')}</select></div><div><label for="count">Nombre de questions</label><select id="count" class="field"><option value="5">5 questions</option><option value="10" selected>10 questions</option><option value="20">20 questions</option><option value="all">Toutes les questions</option></select></div></div><label><input type="checkbox" id="random" checked> Mélanger les questions</label><div class="actions"><button class="primary" onclick="startQuiz()">Commencer / Recommencer</button><span class="badge">Meilleur score : ${store.get('best',0)} %</span></div><div id="quiz-area" style="margin-top:24px"></div></div>`}
function shuffle(a){let x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}function startQuiz(bank){if(!premiumVerified){$('app').innerHTML=quizLocked();return;}let pool=bank||DATA.questions.filter(q=>$('topic').value==='all'||q.topic===Number($('topic').value));if(!bank && $('random').checked)pool=shuffle(pool);if(!bank){let n=$('count').value;pool=pool.slice(0,n==='all'?pool.length:Number(n))}currentQuiz=pool;qIndex=0;score=0;errors=[];renderQuestion()}
function renderQuestion(){if(!premiumVerified){$('app').innerHTML=quizLocked();return;}const q=currentQuiz[qIndex];if(!q){finishQuiz();return}chosen=false;$('quiz-area').innerHTML=`<div class="toolbar"><span class="pill">Question ${qIndex+1} / ${currentQuiz.length}</span><span class="badge">Score : ${score}</span></div><div class="progress"><div style="width:${(qIndex/currentQuiz.length)*100}%"></div></div><h2>${clean(q.question)}</h2><div id="opts">${q.options.map((a,i)=>`<button class="quiz-opt" onclick="answerQuiz(${i})">${'ABCD'[i]}. ${clean(a)}</button>`).join('')}</div><button id="hint-btn" class="ghost" onclick="$('hint').hidden=!$('hint').hidden">Afficher / masquer l’indice</button><p id="hint" class="note" hidden>${clean(q.hint)}</p><div id="feedback" hidden></div><button id="next" class="primary" hidden onclick="qIndex++;renderQuestion()">${qIndex===currentQuiz.length-1?'Voir mon résultat':'Question suivante'} →</button>`}
function answerQuiz(i){if(!premiumVerified)return;if(chosen)return;chosen=true;let q=currentQuiz[qIndex],ok=i===q.correct;if(ok)score++;else errors.push(q);document.querySelectorAll('.quiz-opt').forEach((b,j)=>{b.disabled=true;if(j===q.correct)b.classList.add('good');else if(j===i)b.classList.add('bad')});$('feedback').hidden=false;$('feedback').className='feedback';$('feedback').innerHTML=`<strong>${ok?'Bravo !':'Regardons la correction'}</strong><p>${clean(q.explanation)}</p>`;$('next').hidden=false;$('hint-btn').hidden=true;$('hint').hidden=true}
function finishQuiz(){let pct=currentQuiz.length?Math.round(score/currentQuiz.length*100):0;if(pct>store.get('best',0))store.set('best',pct);$('quiz-area').innerHTML=`<div class="note"><h2>Résultat : ${score} / ${currentQuiz.length} (${pct} %)</h2><p>Tu peux relire tes cours puis recommencer pour progresser.</p><div class="actions"><button class="primary" onclick="startQuiz()">Nouveau quiz</button>${errors.length?'<button class="ghost" onclick="retryErrors()">Revoir mes '+errors.length+' erreur(s)</button>':''}</div></div>`}function retryErrors(){startQuiz([...errors])}
function route(){let page=decodeURIComponent(location.hash.replace(/^#/,'')||'accueil'),app=$('app');let m;if(page==='accueil'||page==='cours'){app.innerHTML=home();if(page==='cours')document.querySelector('.section-head')?.scrollIntoView({block:'start'});let n=store.get('done',[]).length;let p=$('progress-home');if(p)p.textContent=n+'/12 chapitres terminés'}else if(page==='premium'){app.innerHTML=`<div class="eyebrow">Bibliothèque Premium</div><h1>Six cours pour approfondir</h1><p class="lead">48 leçons approfondies, avec exemples et exercices corrigés.</p><div class="grid">${DATA.premium.map((_,i)=>card(i,true)).join('')}</div>`}else if((m=/^c-(\d+)$/.exec(page))&&Number(m[1])<12){app.innerHTML=lesson(Number(m[1]))}else if((m=/^p-(\d+)$/.exec(page))&&Number(m[1])<6){app.innerHTML=premiumLesson(Number(m[1]));loadPremiumLesson(Number(m[1]))}else if(page==='quiz'){if(premiumVerified){app.innerHTML='<p>Chargement sécurisé du quiz…</p>';loadQuiz()}else{app.innerHTML=quizLocked();verifyPremium().then(active=>{if(active && location.hash==='#quiz')route()})}}else if(page==='offres'){app.innerHTML=offers()}else{app.innerHTML=home()}if(page!=='cours')window.scrollTo(0,0);mountAds()}window.addEventListener('hashchange',route);verifyPremium().then(route);

